select * from (select distinct(select FIN_CASH_PAY_RULE.PAY_TYPE from FIN_CASH_PAY_RULE where FIN_CASH_INFO.cash_id = FIN_CASH_PAY_RULE.cash_id AND FIN_CASH_INFO.CASH_TYPE_1 = '02' AND FIN_CASH_INFO.CASH_TYPE_2 = 'C02' and FIN_CASH_PAY_RULE.eff_date = (SELECT MAX(FIN_CASH_PAY_RULE.eff_date) AS max_eff_date FROM FIN_CASH_PAY_RULE WHERE FIN_CASH_INFO.cash_id = FIN_CASH_PAY_RULE.cash_id and PRD_SALE_PARAM.FIRST_SALE_VDATE <= STR_TO_DATE(#{batchDate,jdbcType=DATE}, '%Y-%m-%d'))) bonusMode, (select FIN_CASH_PAY_RULE.PAY_CYCLE from FIN_CASH_PAY_RULE where FIN_CASH_INFO.cash_id = FIN_CASH_PAY_RULE.cash_id AND FIN_CASH_INFO.CASH_TYPE_1 = '02' AND FIN_CASH_INFO.CASH_TYPE_2 = 'C02' and FIN_CASH_PAY_RULE.eff_date = (SELECT MAX(FIN_CASH_PAY_RULE.eff_date) AS max_eff_date FROM FIN_CASH_PAY_RULE WHERE FIN_CASH_INFO.cash_id = FIN_CASH_PAY_RULE.cash_id and PRD_SALE_PARAM.FIRST_SALE_VDATE <= STR_TO_DATE(#{batchDate,jdbcType=DATE}, '%Y-%m-%d'))) intpayPeriod, case FIN_PRODUCT.PROFIT_TYPE when '01' then YJ2.rate when '02' then YJ.yield else YJ2.rate end rate, (case when FIN_PRODUCT_ADD.DEAL_MODE = '11' then (select round(case when SUM(TDY_POSITION) = 0 then 0 else /*nvl2(sum(TDY_POSITION),sum(IFNULL(TDY_POSITION, 0) *IFNULL(TDY_FEE_RATE, 0)) / sum(TDY_POSITION),0)*/ IF(!ISNULL(sum(TDY_POSITION)) ,sum(IFNULL(TDY_POSITION, 0) *IFNULL(TDY_FEE_RATE, 0)) / sum(TDY_POSITION) ,0) end, 4) from BOK_POSITION_PRDFEE bop where bop.FINPROD_ID = fin_product.finprod_id and bop.FEE_TYPE = 'C03' and bop.CDATE = (select MAX(BOK_POSITION_PRDFEE.CDATE) MAX_CDATE from BOK_POSITION_PRDFEE where BOK_POSITION_PRDFEE.FINPROD_ID = fin_product.finprod_id and BOK_POSITION_PRDFEE.FEE_TYPE = 'C03' and BOK_POSITION_PRDFEE.CDATE <= STR_TO_DATE(#{batchDate,jdbcType=DATE}, '%Y-%m-%d'))) else (select IFNULL(TDY_FEE_RATE, 0) from BOK_POSITION_PRDFEE bop where bop.FINPROD_ID = fin_product.FINPROD_ID and bop.FEE_TYPE = 'C03' and bop.CDATE = (select MAX(BOK_POSITION_PRDFEE.CDATE) MAX_CDATE from BOK_POSITION_PRDFEE where BOK_POSITION_PRDFEE.FINPROD_ID = fin_product.finprod_id and BOK_POSITION_PRDFEE.FEE_TYPE = 'C03' and BOK_POSITION_PRDFEE.CDATE <= STR_TO_DATE(#{batchDate,jdbcType=DATE}, '%Y-%m-%d'))) end) * 100 fixFeeProportion, (case when FIN_PRODUCT_ADD.DEAL_MODE = '11' then (select round( case when SUM(TDY_POSITION) = 0 then 0 else /*nvl2(sum(TDY_POSITION),sum(IFNULL(TDY_POSITION, 0) *IFNULL(TDY_FEE_RATE, 0)) / sum(TDY_POSITION),0)*/ IF(!ISNULL(sum(TDY_POSITION)) ,sum(IFNULL(TDY_POSITION, 0) *IFNULL(TDY_FEE_RATE, 0)) / sum(TDY_POSITION) ,0) end,4) from BOK_POSITION_PRDFEE bop where bop.FINPROD_ID = fin_product.finprod_id and bop.FEE_TYPE = 'C05' and bop.CDATE = (select MAX(BOK_POSITION_PRDFEE.CDATE) MAX_CDATE from BOK_POSITION_PRDFEE where BOK_POSITION_PRDFEE.FINPROD_ID = fin_product.finprod_id and BOK_POSITION_PRDFEE.FEE_TYPE = 'C05' and BOK_POSITION_PRDFEE.CDATE <= STR_TO_DATE(#{batchDate,jdbcType=DATE}, '%Y-%m-%d'))) else (select IFNULL(TDY_FEE_RATE, 0) from BOK_POSITION_PRDFEE bop where bop.FINPROD_ID = fin_product.FINPROD_ID and bop.FEE_TYPE = 'C05' and bop.CDATE = (select MAX(BOK_POSITION_PRDFEE.CDATE) MAX_CDATE from BOK_POSITION_PRDFEE where BOK_POSITION_PRDFEE.FINPROD_ID = fin_product.finprod_id and BOK_POSITION_PRDFEE.FEE_TYPE = 'C05' and BOK_POSITION_PRDFEE.CDATE <= STR_TO_DATE(#{batchDate,jdbcType=DATE}, '%Y-%m-%d'))) end) * 100 trustFeeProportion, (select CUS_YEAR_YIELD from CHB_PRD_END_SUB where CHB_PRD_END_SUB.PROD_ID = FIN_PRODUCT.FINPROD_MARKET_ID and CHB_PRD_END_SUB.SEND_STATUS != '01') actYield, (select IFNULL(sum(TRADE_AMT), 0) from (select TOTLE_TRADE_ID, BUSI_TYPE, FINPROD_ID, FINPROD_TYPE2, TRADE_DATE, TRADE_STATUS, PS, TRADE_AMT, INT_AMT, SHARE_AMT, FPRICE_AMT, PRIN_AMT FROM TRD_FIN_PRODUCT_DEAL_TOTAL WHERE trade_status = '01' AND is_cancel = 'N') deal where deal.ps = 'C1' and deal.finprod_id = fin_product.finprod_id and deal.trade_status != '03' group by deal.finprod_id) firstPrinAmt, ((select IFNULL(sum(SHARE_AMT), 0) from (select TOTLE_TRADE_ID, BUSI_TYPE, FINPROD_ID, FINPROD_TYPE2, TRADE_DATE, TRADE_STATUS, PS, TRADE_AMT, INT_AMT, SHARE_AMT, FPRICE_AMT, PRIN_AMT FROM TRD_FIN_PRODUCT_DEAL_TOTAL WHERE trade_status = '01' AND is_cancel = 'N') deal where deal.ps in ('C1', 'C2', 'C3', 'C10') and deal.trade_status != '03' and deal.finprod_id = fin_product.finprod_id and deal.TRADE_DATE <= STR_TO_DATE(#{batchDate,jdbcType=DATE}, '%Y-%m-%d')) - (select IFNULL(sum(SHARE_AMT), 0) from (select TOTLE_TRADE_ID, BUSI_TYPE, FINPROD_ID, FINPROD_TYPE2, TRADE_DATE, TRADE_STATUS, PS, TRADE_AMT, INT_AMT, SHARE_AMT, FPRICE_AMT, PRIN_AMT FROM TRD_FIN_PRODUCT_DEAL_TOTAL WHERE trade_status = '01' AND is_cancel = 'N') deal where deal.ps in ('C6', 'C4', 'C5', 'C17', 'C19', 'C20') and deal.trade_status != '03' and deal.finprod_id = fin_product.finprod_id and deal.TRADE_DATE <= STR_TO_DATE(#{batchDate,jdbcType=DATE}, '%Y-%m-%d'))) shareAmt, (case when fin_product.PROFIT_TYPE = '02' then (select IFNULL(sum(INT_AMT), 0) from (select TOTLE_TRADE_ID, BUSI_TYPE, FINPROD_ID, FINPROD_TYPE2, TRADE_DATE, TRADE_STATUS, PS, TRADE_AMT, INT_AMT, SHARE_AMT, FPRICE_AMT, PRIN_AMT FROM TRD_FIN_PRODUCT_DEAL_TOTAL WHERE trade_status = '01' AND is_cancel = 'N') deal where deal.ps in ('C4', 'C5', 'C17', 'C20') and deal.finprod_id = fin_product.finprod_id and deal.TRADE_DATE <= STR_TO_DATE(#{batchDate,jdbcType=DATE}, '%Y-%m-%d') group by deal.finprod_id) when fin_product.PROFIT_TYPE in ('01', '03') then (select IFNULL(sum(FPRICE_AMT), 0) from (select TOTLE_TRADE_ID, BUSI_TYPE, FINPROD_ID, FINPROD_TYPE2, TRADE_DATE, TRADE_STATUS, PS, TRADE_AMT, INT_AMT, SHARE_AMT, FPRICE_AMT, PRIN_AMT FROM TRD_FIN_PRODUCT_DEAL_TOTAL WHERE trade_status = '01' AND is_cancel = 'N') deal where deal.ps in ('C9', 'C10') and deal.finprod_id = fin_product.finprod_id and deal.TRADE_DATE <= STR_TO_DATE(#{batchDate,jdbcType=DATE}, '%Y-%m-%d') group by deal.finprod_id) else 0 end) custProfit, (select TRADE_AMT from (select FINPROD_ID, PS, FINPROD_TYPE2, IFNULL(sum(TRADE_AMT), 0) TRADE_AMT, IFNULL(sum(SHARE_AMT), 0) SHARE_AMT, IFNULL(sum(INT_AMT), 0) INT_AMT, IFNULL(sum(PRIN_AMT), 0) PRIN_AMT, IFNULL(sum(FPRICE_AMT), 0) FPRICE_AMT FROM TRD_FIN_PRODUCT_DEAL_TOTAL where (TRADE_DATE is null or TRADE_DATE <= STR_TO_DATE(#{batchDate,jdbcType=DATE}, '%Y-%m-%d')) and trade_status = '01' AND is_cancel = 'N' group by FINPROD_ID, PS, FINPROD_TYPE2) deal1 where deal1.ps = 'C11' and deal1.finprod_type2 = 'C05' and deal1.finprod_id = fin_product.finprod_id) trustFee, (select TRADE_AMT from (select FINPROD_ID, PS, FINPROD_TYPE2, IFNULL(sum(TRADE_AMT), 0) TRADE_AMT, IFNULL(sum(SHARE_AMT), 0) SHARE_AMT, IFNULL(sum(INT_AMT), 0) INT_AMT, IFNULL(sum(PRIN_AMT), 0) PRIN_AMT, IFNULL(sum(FPRICE_AMT), 0) FPRICE_AMT FROM TRD_FIN_PRODUCT_DEAL_TOTAL where (TRADE_DATE is null or TRADE_DATE <= STR_TO_DATE(#{batchDate,jdbcType=DATE}, '%Y-%m-%d')) and trade_status = '01' AND is_cancel = 'N' group by FINPROD_ID, PS, FINPROD_TYPE2) deal1 where deal1.ps = 'C11' and deal1.finprod_type2 = 'C06' and deal1.finprod_id = fin_product.finprod_id) saleFee, (select TRADE_AMT from (select FINPROD_ID, PS, FINPROD_TYPE2, IFNULL(sum(TRADE_AMT), 0) TRADE_AMT, IFNULL(sum(SHARE_AMT), 0) SHARE_AMT, IFNULL(sum(INT_AMT), 0) INT_AMT, IFNULL(sum(PRIN_AMT), 0) PRIN_AMT, IFNULL(sum(FPRICE_AMT), 0) FPRICE_AMT FROM TRD_FIN_PRODUCT_DEAL_TOTAL where (TRADE_DATE is null or TRADE_DATE <= STR_TO_DATE(#{batchDate,jdbcType=DATE}, '%Y-%m-%d')) and trade_status = '01' AND is_cancel = 'N' group by FINPROD_ID, PS, FINPROD_TYPE2) deal1 where deal1.ps = 'C11' and deal1.finprod_type2 = 'C03' and deal1.finprod_id = fin_product.finprod_id) fixFee, (select TRADE_AMT from (select FINPROD_ID, PS, FINPROD_TYPE2, IFNULL(sum(TRADE_AMT), 0) TRADE_AMT, IFNULL(sum(SHARE_AMT), 0) SHARE_AMT, IFNULL(sum(INT_AMT), 0) INT_AMT, IFNULL(sum(PRIN_AMT), 0) PRIN_AMT, IFNULL(sum(FPRICE_AMT), 0) FPRICE_AMT FROM TRD_FIN_PRODUCT_DEAL_TOTAL where (TRADE_DATE is null or TRADE_DATE <= STR_TO_DATE(#{batchDate,jdbcType=DATE}, '%Y-%m-%d')) and trade_status = '01' AND is_cancel = 'N' group by FINPROD_ID, PS, FINPROD_TYPE2) deal1 where deal1.ps = 'C11' and deal1.finprod_type2 = 'C10' and deal1.finprod_id = fin_product.finprod_id) proxyFee, (select TRADE_AMT from (select FINPROD_ID, PS, FINPROD_TYPE2, IFNULL(sum(TRADE_AMT), 0) TRADE_AMT, IFNULL(sum(SHARE_AMT), 0) SHARE_AMT, IFNULL(sum(INT_AMT), 0) INT_AMT, IFNULL(sum(PRIN_AMT), 0) PRIN_AMT, IFNULL(sum(FPRICE_AMT), 0) FPRICE_AMT FROM TRD_FIN_PRODUCT_DEAL_TOTAL where (TRADE_DATE is null or TRADE_DATE <= STR_TO_DATE(#{batchDate,jdbcType=DATE}, '%Y-%m-%d')) and trade_status = '01' AND is_cancel = 'N' group by FINPROD_ID, PS, FINPROD_TYPE2) deal1 where deal1.ps = 'C12' and deal1.finprod_type2 is null and deal1.finprod_id = fin_product.finprod_id) addTax, (case when fin_product.PROFIT_TYPE in ('01', '03') then (select TRADE_AMT from (select FINPROD_ID, PS, FINPROD_TYPE2, IFNULL(sum(TRADE_AMT), 0) TRADE_AMT, IFNULL(sum(SHARE_AMT), 0) SHARE_AMT, IFNULL(sum(INT_AMT), 0) INT_AMT, IFNULL(sum(PRIN_AMT), 0) PRIN_AMT, IFNULL(sum(FPRICE_AMT), 0) FPRICE_AMT FROM TRD_FIN_PRODUCT_DEAL_TOTAL where (TRADE_DATE is null or TRADE_DATE <= STR_TO_DATE(#{batchDate,jdbcType=DATE}, '%Y-%m-%d')) and trade_status = '01' AND is_cancel = 'N' group by FINPROD_ID, PS, FINPROD_TYPE2) deal1 where deal1.ps = 'C11' and deal1.finprod_type2 = 'C04' and deal1.finprod_id = fin_product.finprod_id) end) floatFee, (select sum(TRADE_AMT) from (select FINPROD_ID, PS, FINPROD_TYPE2, IFNULL(sum(TRADE_AMT), 0) TRADE_AMT, IFNULL(sum(SHARE_AMT), 0) SHARE_AMT, IFNULL(sum(INT_AMT), 0) INT_AMT, IFNULL(sum(PRIN_AMT), 0) PRIN_AMT, IFNULL(sum(FPRICE_AMT), 0) FPRICE_AMT FROM TRD_FIN_PRODUCT_DEAL_TOTAL where (TRADE_DATE is null or TRADE_DATE <= STR_TO_DATE(#{batchDate,jdbcType=DATE}, '%Y-%m-%d')) and trade_status = '01' AND is_cancel = 'N' group by FINPROD_ID, PS, FINPROD_TYPE2) deal1 where deal1.ps = 'C11' and deal1.finprod_type2 is not null and deal1.finprod_type2 not in ('C03', 'C04', 'C05', '04', 'C06', 'C10') and deal1.finprod_id = fin_product.finprod_id group by deal1.finprod_id) otherFee, (select sum(TRADE_AMT) from (select FINPROD_ID, PS, FINPROD_TYPE2, IFNULL(sum(TRADE_AMT), 0) TRADE_AMT, IFNULL(sum(SHARE_AMT), 0) SHARE_AMT, IFNULL(sum(INT_AMT), 0) INT_AMT, IFNULL(sum(PRIN_AMT), 0) PRIN_AMT, IFNULL(sum(FPRICE_AMT), 0) FPRICE_AMT FROM TRD_FIN_PRODUCT_DEAL_TOTAL where (TRADE_DATE is null or TRADE_DATE <= STR_TO_DATE(#{batchDate,jdbcType=DATE}, '%Y-%m-%d')) and trade_status = '01' AND is_cancel = 'N' group by FINPROD_ID, PS, FINPROD_TYPE2) deal1 where deal1.ps = 'C11' and deal1.finprod_type2 in ('12', '04') and deal1.finprod_id = fin_product.finprod_id) actMidIncome, (select IFNULL(sum(TRADE_AMT), 0) from deal where deal.ps in ('C1', 'C2') and deal.finprod_id = fin_product.finprod_id and (deal.TRADE_DATE is null or (deal.TRADE_DATE <= STR_TO_DATE(#{batchDate,jdbcType=DATE}, '%Y-%m-%d') and deal.TRADE_DATE >= STR_TO_DATE(#{queryDateStart,jdbcType=DATE}, '%Y-%m-%d'))) group by deal.finprod_id) monthIssuePrinamt, (select IFNULL(sum(SHARE_AMT), 0) from deal where deal.ps in ('C1', 'C2') and deal.finprod_id = fin_product.finprod_id and (deal.TRADE_DATE is null or (deal.TRADE_DATE <= STR_TO_DATE(#{batchDate,jdbcType=DATE}, '%Y-%m-%d') and deal.TRADE_DATE >= STR_TO_DATE(#{queryDateStart,jdbcType=DATE}, '%Y-%m-%d'))) group by deal.finprod_id) monthIssueShareamt, (select IFNULL(sum(TRADE_AMT), 0) from deal where deal.ps in ('C4', 'C5', 'C17', 'C6', 'C20') and deal.finprod_id = fin_product.finprod_id and (deal.TRADE_DATE is null or (deal.TRADE_DATE <= STR_TO_DATE(#{batchDate,jdbcType=DATE}, '%Y-%m-%d') and deal.TRADE_DATE >= STR_TO_DATE(#{queryDateStart,jdbcType=DATE}, '%Y-%m-%d'))) group by deal.finprod_id) monthDuePrinamt, (select IFNULL(sum(SHARE_AMT), 0) from deal where deal.ps in ('C4', 'C5', 'C17', 'C6', 'C20') and deal.finprod_id = fin_product.finprod_id and (deal.TRADE_DATE is null or (deal.TRADE_DATE <= STR_TO_DATE(#{batchDate,jdbcType=DATE}, '%Y-%m-%d') and deal.TRADE_DATE >= STR_TO_DATE(#{queryDateStart,jdbcType=DATE}, '%Y-%m-%d'))) group by deal.finprod_id) monthDueShareamt, FIN_PRODUCT.FINPROD_ID finprodId, FIN_PRODUCT.PROFIT_TYPE profitType, FIN_PRODUCT_ADD.DEAL_MODE dealMode from FIN_PRODUCT left join FIN_PRODUCT_ADD on FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID left join PTL_PORTFOLIO_AUTHORITY on FIN_PRODUCT_ADD.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID left join FIN_CASH_INFO on FIN_PRODUCT.FINPROD_ID = FIN_CASH_INFO.FINPROD_ID and FIN_CASH_INFO.FINPROD_TYPE = '01' and FIN_CASH_INFO.CASH_TYPE_1 = '02' and FIN_CASH_INFO.CASH_TYPE_2 = 'C02' and FIN_CASH_INFO.BRANCH = 0 left join PRD_SALE_PARAM on FIN_PRODUCT.FINPROD_ID = PRD_SALE_PARAM.FINPROD_ID left join FIN_BASE_RULE_INFO ON FIN_PRODUCT.FINPROD_ID = FIN_BASE_RULE_INFO.FINPROD_ID AND FIN_BASE_RULE_INFO.BASE_RULE_TYPE = '01' and FIN_BASE_RULE_INFO.EFF_DATE = FIN_PRODUCT.VDATE LEFT JOIN (select IFNULL(PRO.P_FINPROD_ID, pro.finprod_id) finprod_id, group_concat(t.YIELD * 100 ORDER BY t.eff_date separator '/') yield from fin_cash_calc_rule t LEFT JOIN FIN_CASH_INFO CASH ON T.CASH_ID = CASH.CASH_ID and cash.cash_type_1 = '02' and cash.cash_type_2 = 'C02' left join fin_product pro on cash.finprod_id = pro.finprod_id where pro.profit_type = '02' and (t.eff_date, t.cash_id) in (select max(eff_date), cash_id from FIN_CASH_CALC_RULE where eff_date <= STR_TO_DATE(#{batchDate,jdbcType=DATE}, '%Y-%m-%d') group by cash_id) group by IFNULL(PRO.P_FINPROD_ID, pro.finprod_id)) YJ on YJ.finprod_id = FIN_PRODUCT.FINPROD_ID LEFT JOIN (select IFNULL(PRO.P_FINPROD_ID, pro.finprod_id) finprod_id, group_concat(t.rate * 100 ORDER BY t.eff_date separator '/') rate from FIN_BASE_RULE_INFO t left join fin_product pro on t.finprod_id = pro.finprod_id where pro.profit_type != '02' and t.BASE_RULE_TYPE = '02' and (t.eff_date, t.finprod_id) in (select max(eff_date), finprod_id from FIN_CASH_CALC_RULE where eff_date <= STR_TO_DATE(#{batchDate,jdbcType=DATE}, '%Y-%m-%d') group by finprod_id) group by IFNULL(PRO.P_FINPROD_ID, pro.finprod_id)) YJ2 on YJ2.finprod_id = FIN_PRODUCT.FINPROD_ID where FIN_PRODUCT.P_FINPROD_ID IS NULL and PRD_SALE_PARAM.FIRST_SALE_VDATE <= STR_TO_DATE(#{batchDate,jdbcType=DATE}, '%Y-%m-%d')
and (
)
) order by finprodId

select * from FIN_BASE_RULE_INFO
where FINPROD_ID = #{finProdId,jdbcType=VARCHAR}
AND BRANCH = #{finBrach,jdbcType=INTEGER}
AND BASE_RULE_TYPE = #{finBaseRuleType,jdbcType=VARCHAR}

	and EFF_DATE <= 
	STR_TO_DATE(#{queryDate}, '%Y-%m-%d')

ORDER BY EFF_DATE DESC

select LEV lev, BASE_RULE_ID baseRuleId, COEFFICIENT coefficient, SPREAD_RATE * 100 spreadRate, CHARGE_RATIO * 100 chargeRatio from FIN_FLOAT_CALC_RULE_DETAIL, FIN_CASH_INFO, FIN_PRODUCT, FIN_PRODUCT_ADD where FIN_FLOAT_CALC_RULE_DETAIL.CASH_ID = FIN_CASH_INFO.CASH_ID and FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID and FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID and FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1} and FIN_CASH_INFO.CASH_TYPE_2 = #{cashType2} and FIN_CASH_INFO.BRANCH = 0 AND (FIN_CASH_INFO.FINPROD_ID = #{finprodId}) and FIN_CASH_INFO.FINPROD_TYPE = #{finprodType}
and FIN_FLOAT_CALC_RULE_DETAIL.CASH_ID = #{cashId}
and FIN_FLOAT_CALC_RULE_DETAIL.EFF_DATE = STR_TO_DATE(#{effDate},'%Y-%m-%d')
and (FIN_FLOAT_CALC_RULE_DETAIL.EFF_DATE = FIN_PRODUCT.VDATE OR FIN_PRODUCT.FINPROD_TYPE2= #{finprodType2, jdbcType=VARCHAR})
order by LEV

SELECT FIN_FLOAT_CALC_RULE_DETAIL.LEV lev, FIN_FLOAT_CALC_RULE_DETAIL.SPREAD_RATE*100 spreadRate, FIN_FLOAT_CALC_RULE_DETAIL.BASE_RULE_ID baseRuleId, FIN_FLOAT_CALC_RULE_DETAIL.COEFFICIENT coefficient, FIN_FLOAT_CALC_RULE_DETAIL.CHARGE_RATIO*100 chargeRatio FROM FIN_FLOAT_CALC_RULE_DETAIL
FIN_FLOAT_CALC_RULE_DETAIL.CASH_ID = #{cashId}
AND DATE_FORMAT(FIN_FLOAT_CALC_RULE_DETAIL.EFF_DATE,'%Y-%m-%d') = #{effDate}
ORDER BY FIN_FLOAT_CALC_RULE_DETAIL.LEV ASC

select LEV lev,
BASE_RULE_ID baseRuleId,
COEFFICIENT coefficient,
SPREAD_RATE * 100 spreadRate,
CHARGE_RATIO * 100 chargeRatio
from FIN_FLOAT_CALC_RULE_DETAIL, FIN_CASH_INFO,
FIN_PRODUCT, FIN_PRODUCT_ADD
where FIN_FLOAT_CALC_RULE_DETAIL.CASH_ID =
FIN_CASH_INFO.CASH_ID
and FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID
and FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID
and FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1}
and FIN_CASH_INFO.CASH_TYPE_2 = #{cashType2}
and FIN_CASH_INFO.BRANCH = 0
AND ((FIN_CASH_INFO.FINPROD_ID = #{finprodId} and
FIN_PRODUCT_ADD.DEAL_MODE != #{dealMode10})
OR (FIN_PRODUCT.P_FINPROD_ID = #{finprodId} and
FIN_PRODUCT_ADD.DEAL_MODE = #{dealMode10}
AND FIN_PRODUCT_ADD.TERM_TYPE != #{termType02}))
and FIN_CASH_INFO.FINPROD_TYPE = #{finprodType}

	and FIN_FLOAT_CALC_RULE_DETAIL.CASH_ID = #{cashId}

and FIN_FLOAT_CALC_RULE_DETAIL.EFF_DATE = (
select MAX(FIN_FLOAT_CALC_RULE_DETAIL.EFF_DATE)
from FIN_FLOAT_CALC_RULE_DETAIL, FIN_CASH_INFO, FIN_PRODUCT,
FIN_PRODUCT_ADD
where FIN_FLOAT_CALC_RULE_DETAIL.CASH_ID = FIN_CASH_INFO.CASH_ID
and FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID
and FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID
and FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1}
and FIN_CASH_INFO.CASH_TYPE_2 = #{cashType2}
and FIN_CASH_INFO.BRANCH = 0
and FIN_FLOAT_CALC_RULE_DETAIL.EFF_DATE <= STR_TO_DATE(#{queryDate},
'%Y-%m-%d')
AND ((FIN_CASH_INFO.FINPROD_ID = #{finprodId} and
FIN_PRODUCT_ADD.DEAL_MODE != #{dealMode10})
OR (FIN_PRODUCT.P_FINPROD_ID = #{finprodId} and
FIN_PRODUCT_ADD.DEAL_MODE = #{dealMode10}
AND FIN_PRODUCT_ADD.TERM_TYPE != #{termType02}))
and FIN_CASH_INFO.FINPROD_TYPE = #{finprodType}

	and FIN_FLOAT_CALC_RULE_DETAIL.CASH_ID = #{cashId}

)
order by LEV

select FIN_BASE_RULE_INFO.BASE_RULE_ID baseRuleId, FIN_BASE_RULE_INFO.EFF_DATE effDate, FIN_BASE_RULE_INFO.RATE_TYPE rateType, FIN_BASE_RULE_INFO.RATE*100 rate, FIN_BASE_RULE_INFO.COEFFICIENT coefficient, FIN_BASE_RULE_INFO.INDEX_ID indexId, FIN_BASE_RULE_INFO.INDEX_SOURCE indexSource, FIN_BASE_RULE_INFO.SPREAD_RATE*100 spreadRate, FIN_BASE_RULE_INFO.RESET_TYPE resetType, prd_layer_param.PROD_STYLE prodStyle, prd_layer_param.TERM_MAX investmentCycle, FIN_BASE_RULE_INFO.BASE_RULE_TYPE baseRuleType, FIN_BASE_RULE_INFO.PUBLISH_TYPE publishType, FIN_BASE_RULE_INFO.RATE_LOWER*100 rateLower, FIN_BASE_RULE_INFO.RATE_LIMIT*100 rateLimit, FIN_PRODUCT.VDATE vdate, FIN_BASE_RULE_INFO.FINPROD_ID finprodId from FIN_BASE_RULE_INFO, FIN_PRODUCT left join prd_layer_param on FIN_PRODUCT.FINPROD_ID = prd_layer_param.FINPROD_ID where FIN_BASE_RULE_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID and (FIN_BASE_RULE_INFO.FINPROD_ID = #{finprodId,jdbcType=VARCHAR} or prd_layer_param.P_FINPROD_ID = #{finprodId,jdbcType=VARCHAR})
AND FIN_BASE_RULE_INFO.BASE_RULE_TYPE = #{baseRuleType,jdbcType=VARCHAR}
AND FIN_BASE_RULE_INFO.PUBLISH_TYPE = #{publishType,jdbcType=VARCHAR}
and FIN_BASE_RULE_INFO.EFF_DATE = STR_TO_DATE(#{effDate},'%Y-%m-%d')
and (FIN_BASE_RULE_INFO.EFF_DATE = FIN_PRODUCT.VDATE OR FIN_PRODUCT.FINPROD_TYPE2= #{finprodType2, jdbcType=VARCHAR})

select FIN_BASE_RULE_INFO.BASE_RULE_ID baseRuleId, FIN_BASE_RULE_INFO.EFF_DATE effDate, FIN_BASE_RULE_INFO.RATE_TYPE rateType, FIN_BASE_RULE_INFO.RATE*100 rate, FIN_BASE_RULE_INFO.COEFFICIENT coefficient, FIN_BASE_RULE_INFO.INDEX_ID indexId, FIN_BASE_RULE_INFO.INDEX_SOURCE indexSource, FIN_BASE_RULE_INFO.SPREAD_RATE*100 spreadRate, FIN_BASE_RULE_INFO.RESET_TYPE resetType, FIN_BASE_RULE_INFO.BASE_RULE_TYPE baseRuleType, FIN_BASE_RULE_INFO.PUBLISH_TYPE publishType, FIN_BASE_RULE_INFO.RATE_LOWER*100 rateLower, FIN_BASE_RULE_INFO.RATE_LIMIT*100 rateLimit, FIN_BASE_RULE_INFO.FINPROD_ID finprodId from FIN_BASE_RULE_INFO where FINPROD_ID = #{finProdId,jdbcType=VARCHAR} AND BRANCH = #{finBrach,jdbcType=INTEGER} AND BASE_RULE_TYPE = #{finBaseRuleType,jdbcType=VARCHAR}
and EFF_DATE <= STR_TO_DATE(#{queryDate}, '%Y-%m-%d')
ORDER BY EFF_DATE DESC

select CUSTOM_LEVEL customLevel, AMT_MIN amtMin, AMT_MAX amtMax, TERM_MAX termMax, TERM_MIN termMin, YIELD * 100 yield, REMARK remark, P_FINPROD_ID pFinprodId, VDATE vdate, IFNULL(PROD_STYLE,TERM_MAX) prodStyle, SALE_CHANNEL saleChannel, SALE_DEPARTMENT saleDepartment, TAR_CUSTOMER_TYPE tarCustomerType, IS_SALE isSale ,FINPROD_ID finprodId from PRD_LAYER_PARAM where 1=1
AND P_FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
and P_FINPROD_ID in (select FINPROD_ID FROM FIN_PRODUCT where FINPROD_MARKET_ID = #{finprodMarketId,jdbcType=VARCHAR} AND p_finprod_id is null)
